    let s = Arc::new(Semaphore::new(2));

    let workers = [
        thread::spawn({
            let s = Arc::clone(&s);
            move || w1(s)
        }),
        thread::spawn({
            let s = Arc::clone(&s);
            move || w2(s)
        }),
        thread::spawn({
            let s = Arc::clone(&s);
            move || w3(s)
        }),
    ];

    for worker in workers {
        worker.join().expect("worker thread panicked");
    }

    println!("DONE done=1");
}
